    <select data-bind="plan" aria-label="Plan">${[['all', 'All Plans'], ...PK.map((k) => [k, PLAN[k][0]])].map(([k, l]) => `<option value="${k}" ${S.plan === k ? 'selected' : ''}>${l}</option>`).join('')}</select>
