    const key = { revenue: (r) => -r.rev, visits: (r) => -r.v, conv: (r) => -(r.o / Math.max(1, r.v)), roas: (r) => -(r.sp ? r.rev / r.sp : 99) }[S.sortCh]; rows = rows.sort((a, b) => key(a) - key(b));
