  function goalProgress() { const day = TODAY.getDate(), dim = new Date(TODAY.getFullYear(), TODAY.getMonth() + 1, 0).getDate(); const A = agg(N - day, N - 1); return GOALS.map((g) => { const v = g.k === 'revenue' ? A.revenue : g.k === 'orders' ? A.orders : g.k === 'signups' ? A.signups : M[g.k][2](A); const additive = ['revenue', 'orders', 'signups'].includes(g.k); const proj = additive ? v / day * dim : v; const set = +g.t > 0; const ok = set && (g.inv ? proj <= g.t : proj >= g.t); return { ...g, v, proj, ok, set, p: !set ? 0 : additive ? v / g.t * 100 : g.inv ? Math.min(100, g.t / Math.max(0.01, v) * 100) : v / g.t * 100 }; }); }
