  function forecast(days) { const out = []; for (let j = 1; j <= days; j++) { const dt = dateOf(N - 1 + j); const bf = promoAt(N - 1 + j) ? S.fc.bf : 1; const v = dowAvg[dt.getDay()] * Math.pow(1 + S.fc.growth / 100, j / 30) * bf; const w = 0.07 + j * 0.0016; out.push({ j, dt, v, lo: v * (1 - w), hi: v * (1 + w), po: v * S.fc.po / 100 }); } return out; }
  const costs = (T) => { const fees = T.sales * COST.proc / 100 + (T.orders + T.resets) * COST.procFix, plat = T.orders * (COST.platEval + COST.data) + T.funded * COST.platFunded, kyc = T.passes * COST.kyc, aff = T.net * COST.affShare / 100 * COST.affRate / 100; return { fees, plat, kyc, aff, ads: T.spend }; };
